{
  "mcqs": [
    {
      "question": "What is the three-way handshake sequence for establishing a TCP connection?",
      "options": [
        "SYN, SYN-ACK, ACK",
        "ACK, SYN, FIN",
        "SYN, ACK, FIN",
        "FIN, SYN, ACK"
      ],
      "answer": "SYN, SYN-ACK, ACK"
